; void jbv_interpret_x86(JbvFastState *state): runs from state->pc until an opcode for C.
jbv_interpret_x86 PROC
    push ebp
    push ebx
    push esi
    push edi
    mov edx, [esp+20]
    push edx                     ; [esp] = state
    mov esi, [edx+0]
    add esi, [edx+12]
    mov edi, [edx+4]
    mov ebp, [edx+8]
    mov ebx, [edx+16]
    mov eax, [edi+ebx*4-4]       ; top of stack (a local if the stack is empty: read only)
    DISPATCH
exit_op:                         ; esi is just past the opcode C has to run
    dec esi
    mov edx, [esp]
    mov eax, esi
    sub eax, [edx+0]
    mov [edx+12], eax
    mov [edx+16], ebx
    cmp BYTE PTR [edx+158], 0
    jne frame_in_c
    pop edx
    pop edi
    pop esi
    pop ebx
    pop ebp
    ret
frame_in_c:                      ; a core activation: C runs it to its end
    mov ecx, edx
    call @jbv_core_finish@4
    jmp core_return

